static size_t numof_slashes(const char *str)
{
  const char *slashPos;
  size_t num = 0;
  do {
    slashPos = strchr(str, '/');
    if(slashPos) {
      ++num;
      str = slashPos + 1;
    }
  } while(slashPos);
  return num;
}

